mapper.insert:
INSERT INTO BOARD_POST (
    POST_ID, BOARD_TYPE, TITLE, CONTENT, CATEGORY, OPEN_SCOPE, PINNED_YN,
    VIEW_COUNT, WRITER, WRITER_DEPT, CREATED_AT
) VALUES (
    #{postId}, #{boardType}, #{title}, #{content, jdbcType=CLOB}, #{category}, #{openScope}, #{pinnedYn},
    0, #{writer}, #{writerDept}, #{createdAt}
)

mapper.select:
SELECT * FROM (
    SELECT POST_ID, BOARD_TYPE, TITLE, CATEGORY, OPEN_SCOPE, PINNED_YN, VIEW_COUNT,
           WRITER, WRITER_DEPT, CREATED_AT
      FROM BOARD_POST

     ORDER BY CASE WHEN PINNED_YN = 'Y' THEN 0 ELSE 1 END, CREATED_AT DESC, POST_ID DESC
) WHERE ROWNUM <= #{limit}
